/* PG17 facts recorded by autoconf on i686 GNU/Linux, where double and long long members
   are 4-byte aligned although _Alignof reports 8. */
#define ALIGNOF_DOUBLE 4
#define ALIGNOF_INT 4
#define ALIGNOF_LONG 4
#define ALIGNOF_LONG_LONG_INT 4
#define ALIGNOF_SHORT 2
#define HAVE_LONG_LONG_INT_64 1
#define MAXIMUM_ALIGNOF 4
#define PG_INT64_TYPE long long int
#define PG_MAJORVERSION_NUM 17
#define PG_VERSION_NUM 170005
#define PG_VERSION_STR "PostgreSQL 17.5 on i686-pc-linux-gnu, compiled by gcc (Debian 12.2.0-14) 12.2.0, 32-bit"
#define SIZEOF_BOOL 1
#define SIZEOF_LONG 4
#define SIZEOF_SIZE_T 4
#define SIZEOF_VOID_P 4
